--
-- Name: syncConnectedAccountScopeAndVisibility(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core."syncConnectedAccountScopeAndVisibility"() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      BEGIN
        IF TG_OP = 'INSERT' THEN
          IF NEW."visibility" IS NOT NULL THEN
            NEW."scope" := upper(NEW."visibility");
          ELSE
            NEW."visibility" := lower(NEW."scope");
          END IF;
        ELSIF NEW."scope" IS DISTINCT FROM OLD."scope" THEN
          NEW."visibility" := lower(NEW."scope");
        ELSIF NEW."visibility" IS DISTINCT FROM OLD."visibility" THEN
          NEW."scope" := upper(NEW."visibility");
        END IF;
        RETURN NEW;
      END;
      $$;


--
-- Name: unaccent_immutable(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unaccent_immutable(input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
        SELECT public.unaccent('public.unaccent'::regdictionary, input)
        $$;


