    "conditionalPinnedExpression" character varying,
    "coreWorkflowVersionId" uuid,
    CONSTRAINT "CHK_CMD_MENU_ITEM_ENGINE_KEY_COHERENCE" CHECK ((((("engineComponentKey")::text = 'TRIGGER_WORKFLOW_VERSION'::text) AND (("workflowVersionId" IS NOT NULL) OR ("coreWorkflowVersionId" IS NOT NULL)) AND ("frontComponentId" IS NULL) AND (payload IS NULL) AND ("navigationTargetObjectMetadataId" IS NULL)) OR ((("engineComponentKey")::text = 'FRONT_COMPONENT_RENDERER'::text) AND ("frontComponentId" IS NOT NULL) AND ("workflowVersionId" IS NULL) AND ("coreWorkflowVersionId" IS NULL) AND (payload IS NULL) AND ("navigationTargetObjectMetadataId" IS NULL)) OR ((("engineComponentKey")::text = 'NAVIGATION'::text) AND (((payload IS NOT NULL) AND ("navigationTargetObjectMetadataId" IS NULL)) OR ((payload IS NULL) AND ("navigationTargetObjectMetadataId" IS NOT NULL))) AND ("workflowVersionId" IS NULL) AND ("coreWorkflowVersionId" IS NULL) AND ("frontComponentId" IS NULL)) OR ((("engineComponentKey")::text <> ALL (ARRAY[('TRIGGER_WORKFLOW_VERSION'::character varying)::text, ('FRONT_COMPONENT_RENDERER'::character varying)::text, ('NAVIGATION'::character varying)::text])) AND ("workflowVersionId" IS NULL) AND ("coreWorkflowVersionId" IS NULL) AND ("frontComponentId" IS NULL) AND (payload IS NULL) AND ("navigationTargetObjectMetadataId" IS NULL))))
);


