able-templates-tool.ts", "toolTriggerSettings": {"inputSchema": {"type": "object", "required": ["personId"], "properties": {"after": {"type": "string", "description": "Opaque cursor returned by the previous call."}, "first": {"type": "integer", "maximum": 50, "minimum": 1, "description": "Page size; defaults to 20 and never exceeds 50."}, "category": {"enum": ["MARKETING", "UTILITY", "AUTHENTICATION"], "type": "string", "description": "Optional business-purpose filter."}, "language": {"type": "string", "description": "Optional exact Meta language code, for example pt_BR, pt_PT or en_US."}, "personId": {"type": "string", "description": "Exact Twenty Person record id. Resolve a unique Person with Twenty MCP first."}, "accountId": {"type": "string", "description": "Optional WhatsApp account record id. Omit only when exactly one connected account exists."}, "nameContains": {"type": "string", "description": "Optional case-insensitive template-name fragment."}}, "additionalProperties": false}}, "universalIdentifier": "35216977-0ac5-47ce-9610-f3e47fd37d37", "builtHandlerChecksum": "7488229778248f55379b72e8d2537508"}, {"name": "wa-media-worker", "description": "Downloads inbound WhatsApp media and attaches it to the message record.", "handlerName": "default.config.handler", "timeoutSeconds": 120, "builtHandlerPath": "src/logic-functions/wa-media-worker.mjs", "sourceHandlerPath": "src/logic-functions/wa-media-worker.ts", "universalIdentifier": "411818b2-ddfb-417b-8935-950eb5e25d91", "builtHandlerChecksum": "39066f8eb2457f509a765a1b634a2610"}, {"name": "wa-webhook-replay-route", "description": "Lists the raw webhook log and re-drives stored deliveries through the original processors.", "handlerName": "default.config.handler", "timeoutSeconds": 120, "builtHandlerPath": "src/logic-functions/wa-webhook-replay-route.mjs", "sourceHandlerPath": "src/logic-functions/wa-webhook-replay-route.ts", "universalIdentifier": "416e05c5-968a-462a-b0b8-48cc34c63d7f", "builtHandlerChecksum": "c