ete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "personId"}, "universalIdentifier": "485cd574-75f6-4e39-ba89-2b6df2a30129", "objectUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2", "relationTargetFieldMetadataUniversalIdentifier": "79f0739a-fa06-46e7-a8c7-4ddebc5f85ae", "relationTargetObjectMetadataUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconSignature", "name": "signatureRequests", "type": "RELATION", "label": "Signature requests", "isNullable": true, "description": "Documents sent for signature from this person.", "isUIEditable": false, "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "79f0739a-fa06-46e7-a8c7-4ddebc5f85ae", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213", "relationTargetFieldMetadataUniversalIdentifier": "485cd574-75f6-4e39-ba89-2b6df2a30129", "relationTargetObjectMetadataUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2"}, {"icon": "IconSignature", "name": "signatureRequests", "type": "RELATION", "label": "Signature requests", "isNullable": true, "description": "Documents sent for signature from this opportunity.", "isUIEditable": false, "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "bb9f17cb-af93-4f77-9459-e55948b5d2df", "objectUniversalIdentifier": "20202020-9549-49dd-b2b2-883999db8938", "relationTargetFieldMetadataUniversalIdentifier": "f8a0133d-d2a4-42fa-b7c5-6d99e93a3568", "relationTargetObjectMetadataUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2"}, {"icon": "IconSignature", "name": "signatureRequest", "type": "RELATION", "label": "Signature request", "isNullable": true, "description": "The request this signer belongs to.", "universalSettings": {"onDelete": "CASCADE", "relationType": "MANY_TO_ONE", "joinColumnName": "signatureRequestId"}, "universalIdentifier": "d78b6023-d4fa-46c1-8833-9a490314d114", "objectUniversalIdentifier": "b55090b6-fad7-4729-9e23-622624ed6289", "relationTargetFieldMetadataUniversalIdentifier": "dd2bb659-72b3-4172-b6da-5f33263a7271", "relationTargetObjectMetadataUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2"}, {"icon": "IconUserCheck", "name": "signers", "type": "RELATION", "label": "Signers", "isNullable": true, "description": "Everyone asked to sign this document.", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "dd2bb659-72b3-4172-b6da-5f33263a7271", "objectUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2", "relationTargetFieldMetadataUniversalIdentifier": "d78b6023-d4fa-46c1-8833-9a490314d114", "relationTargetObjectMetadataUniversalIdentifier": "b55090b6-fad7-4729-9e23-622624ed6289"}, {"icon": "IconTargetArrow", "name": "opportunity", "type": "RELATION", "label": "Opportunity", "isNullable": true, "description": "The opportunity this document was sent from.", "universalSettings": {"onDelete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "opportunityId"}, "universalIdentifier": "f8a0133d-d2a4-42fa-b7c5-6d99e93a3568", "objectUniversalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2", "relationTargetFieldMetadataUniversalIdentifier": "bb9f17cb-af93-4f77-9459-e55948b5d2df", "relationTargetObjectMetadataUniversalIdentifier": "20202020-9549-49dd-b2b2-883999db8938"}], "skills": [], "indexes": [], "objects": [{"icon": "IconSignature", "fields": [{"icon": "IconAbc", "name": "name", "type": "TEXT", "label": "Name", "description": "Document name as it appears to the signers.", "universalIdentifier": "cd7221cb-68a5-4b93-beda-4c473e6baa73"}, {"icon": "IconProgress", "name": "status", "type": "SELECT", "label": "Status", "options": [{"id": "79b818f4-afb3-47ae-9ae3-5ebae28d769c", "color": "gray", "label": "Pending", "value": "PENDING", "position": 0}, {"id": "9152b0d4-f8df-46f8-9623-ae91ea3fdfe7", "color": "blue", "label": "Sent", "value": "SENT", "position": 1}, {"id": "283b3e33-7d01-421a-8002-b98f43818ca5", "color": "green", "label": "Completed", "value": "COMPLETED", "position": 2}, {"id": "e1ddd938-1081-410d-bd26-b0407aeebffb", "color": "red", "label": "Declined", "value": "DECLINED", "position": 3}, {"id": "e6a8cd23-4f17-467d-8a83-b48932537e9e", "color": "orange", "label": "Expired", "value": "EXPIRED", "position": 4}, {"id": "1330f1c4-4780-4c65-ba8c-2bc1fec2a3ea", "color": "red", "label": "Failed", "value": "FAILED", "position": 5}], "description": "Where this request stands.", "defaultValue": "'PENDING'", "universalIdentifier": "0f4cfc67-c4d7-4e7f-8f04-8f7613d20c70"}, {"icon": "IconHash", "name": "autosignlyDocumentId", "type": "TEXT", "label": "Autosignly document ID", "description": "Identifier of the document in Autosignly.", "universalIdentifier": "b4525a38-1386-4541-864d-8d1de71ce03f"}, {"icon": "IconPaperclip", "name": "sourceFileName", "type": "TEXT", "label": "Source file", "description": "The attachment that was sent for signature.", "universalIdentifier": "d195ba15-d857-400d-9f2e-4aea78edf6fb"}, {"icon": "IconPaperclip", "name": "sourceAttachmentId", "type": "TEXT", "label": "Source attachment", "description": "Identifier of the attachment that was sent, so the same file is not sent twice while a request is still open.", "universalIdentifier": "1d461e43-dae3-4f96-bcc5-6ba4644c7895"}, {"icon": "IconFileTypePdf", "name": "signedDocument", "type": "FILES", "label": "Signed document", "description": "The signed PDF, written back when every signer is done.", "universalSettings": {"maxNumberOfValues": 1}, "universalIdentifier": "af2eeb93-4625-4085-8b46-ba3e2bcfd361"}, {"icon": "IconLink", "name": "signingLink", "type": "LINKS", "label": "Sandbox signing link", "description": "Direct signing page for the signer whose turn it is. A sandbox emails nobody, so this is the only way in; in production Autosignly returns no link here and emails each signer their own.", "universalIdentifier": "e0f4c8a0-8fcf-46f0-8580-936aa5098c9d"}, {"icon": "IconClockHour4", "name": "signingLinkExpiresAt", "type": "DATE_TIME", "label": "Link expires at", "description": "When the signing link stops working.", "universalIdentifier": "ddcb672d-5417-431a-ba85-27b872e30dc9"}, {"icon": "IconFlask", "name": "environment", "type": "TEXT", "label": "Environment", "description": "PROD or SANDBOX, taken from the API key that sent it.", "universalIdentifier": "0de1b35d-b9f8-4a9b-a4e5-d6e90794c552"}, {"icon": "IconSend", "name": "sentAt", "type": "DATE_TIME", "label": "Sent at", "description": "When the document went out for signature.", "universalIdentifier": "8c327226-3302-42a7-a01c-daf53a4890a5"}, {"icon": "IconCalendarCheck", "name": "completedAt", "type": "DATE_TIME", "label": "Completed at", "description": "When the request reached a final state.", "universalIdentifier": "d0c8783f-70fd-4c09-8544-18eb74ce570f"}, {"icon": "IconAlertTriangle", "name": "errorMessage", "type": "TEXT", "label": "Error", "description": "Why the request failed, when it did.", "universalIdentifier": "16107a06-e45f-4a9b-ae20-f941f530bcf6"}], "namePlural": "signatureRequests", "description": "A document sent to Autosignly for electronic signature. Created by the app when a document goes out, never by hand: use Send for signature on the record the document belongs to.", "labelPlural": "Signature requests", "isUIEditable": false, "nameSingular": "signatureRequest", "isUICreatable": false, "labelSingular": "Signature request", "universalIdentifier": "af5eb497-2345-465c-af96-7dfb39ac02c2", "labelIdentifierFieldMetadataUniversalIdentifier": "cd7221cb-68a5-4b93-beda-4c473e6baa73"}, {"icon": "IconUserCheck", "fields": [{"icon": "IconUser", "name": "name", "type": "TEXT", "label": "Name", "description": "Full name of the signer.", "universalIdentifier": "2fad4d7a-5206-4b47-8204-4474679abc19"}, {"icon": "IconMail", "name": "email", "type": "TEXT", "label": "Email", "description": "Where the signing invitation is sent.", "universalIdentifier": "d6df2460-7ff4-4209-bbc0-064cf6dc054b"}, {"icon": "IconFlag", "name": "country", "type": "TEXT", "label": "Country", "description": "ISO 3166-1 alpha-2 code. Decides which signature policy applies.", "universalIdentifier": "aa7b7d65-dc21-4eae-9737-a52d692ea657"}, {"icon": "IconPhone", "name": "phoneNumber", "type": "TEXT", "label": "Phone number", "description": "E.164 number, required when identity is verified by SMS.", "universalIdentifier": "59cbfdcf-b243-4f3f-b6c1-a005d631a343"}, {"icon": "IconCertificate", "name": "signatureType", "type": "TEXT", "label": "Signature type", "description": "Signature level asked of this signer.", "universalIdentifier": "a946211f-a1c0-4e25-8a5f-7d0b3ebb585b"}, {"icon": "IconShieldCheck", "name": "verificationMethod", "type": "TEXT", "label": "Verification method", "description": "How this signer confirms their identity.", "universalIdentifier": "a0f0a5f4-6d66-4840-b43e-eb016ee5d430"}, {"icon": "IconProgress", "name": "status", "type": "SELECT", "label": "Status", "options": [{"id": "c1385e5f-62d6-45ee-a1a5-2c7e1055c95f", "color": "gray", "label": "Pending", "value": "PENDING", "position": 0}, {"id": "e44015ed-2461-4d33-8a07-33e205797943", "color": "green", "label": "Signed", "value": "SIGNED", "position": 1}, {"id": "570d3503-a341-48ed-9d7a-7a3d03f1ca5a", "color": "red", "label": "Declined", "value": "DECLINED", "position": 2}], "description": "Whether this signer is done.", "defaultValue": "'PENDING'", "universalIdentifier": "a21f6e6d-b28b-4180-9b7d-2a41368d90c7"}, {"icon": "IconSortAscending", "name": "signingOrder", "type": "NUMBER", "label": "Order", "description": "Position in the signing order, starting at 1.", "universalIdentifier": "006af919-8609-4a82-bc1a-eb3aafe06033"}, {"icon": "IconCalendarCheck", "name": "signedAt", "type": "DATE_TIME", "label": "Signed at", "description": "When this signer finished.", "universalIdentifier": "077b250a-928d-4287-ad89-699fe0a3db89"}], "namePlural": "documentSigners", "description": "One person asked to sign a document. Written by the app from the signature request, never by hand.", "labelPlural": "Signers", "isUIEditable": false, "nameSingular": "documentSigner", "isUICreatable": false, "labelSingular": "Signer", "universalIdentifier": "b55090b6-fad7-4729-9e23-622624ed6289", "labelIdentifierFieldMetadataUniversalIdentifier": "2fad4d7a-5206-4b47-8204-4474679abc19"}], "viewFields": [], "application": {"logo": "public/autosignly.png", "author": "16it", "category": "Productivity", "termsUrl": "https://autosignly.eu/terms", "websiteUrl": "https://autosignly.eu", "description": "E-signature with eIDAS, pay-as-you-go. Sign from any record, get the PDF back.", "displayName": "Autosignly", "emailSupport": "support@autosignly.eu", "galleryImages": ["public/gallery/01-send-for-signature.png", "public/gallery/02-multiple-signers.png", "public/gallery/03-signature-status.png", "public/gallery/04-settings.png"], "issueReportUrl": "https://github.com/16it-pl/autosignly-integrations/issues", "aboutDescription": "# Autosignly for Twenty\\n\\nSend a document straight from a CRM record for electronic signature, and get the\\nsigned PDF back on that same record.\\n\\nBuilt on [Autosignly](https://autosignly.eu), a European e-signature API.\\nPay as you go, no subscription, and free sandboxes so you can try the whole\\nflow before spending anything.\\n\\n## What it does\\n\\n- **Send for signature** from the command menu on a Person, Company or\\n  Opportunity. Pick one of the record's attachments, pick who signs, send.\\n- **Signer details are prefilled** from the record: name, email, phone, and the\\n  country taken from the phone number.\\n- **Only valid options are offered.** The signature levels and identity checks\\n  shown are the ones Autosignly actually allows for that signer's country, read\\n  live from the API.\\n- **Bad SMS numbers are caught before sending.** A number Autosignly cannot\\n  deliver a code to is normally only refused once the signer asks for the code,\\n  long after the document went out. This app blocks it in the form instead.\\n- **The attachment is replaced with the signed file**, after every signature,\\n  not only the last one. The file on the record is always the document as it\\n  has actually been signed so far, under the same name it went out with.\\n- **The signed PDF comes back automatically** and is attached to the signature\\n  request, along with the status of every signer.\\n\\n## Setup\\n\\nThree steps, and step 2 hands you what step 3 needs.\\n\\n### 1. Paste your API credentials\\n\\nIn Autosignly, go to **Settings → API keys** and create a key. Copy the key and\\nthe secret (the secret is shown once).\\n\\nIn Twenty, go to **Settings → Applications → Autosignly** and paste both into\\n**API key** and **API secret**.\\n\\nSandbox keys work here and cost nothing, so you can wire the whole thing up\\nagainst a sandbox environment first.\\n\\n### 2. Get your webhook URL\\n\\nStill in the Twenty settings panel, press **Check credentials and show URL**.\\n\\nThe app validates the credentials against Autosignly, tells you which company\\nand environment they belong to, and prints a webhook URL that looks like this:\\n\\n```\\nhttps://your-twenty-server.com/webhooks/server/<id>?c=<token>\\n```\\n\\nThe token in that URL is what ties deliveries back to your workspace, so treat\\nthe URL as private and do not share it between workspaces.\\n\\n### 3. Register the URL and paste the signing key back\\n\\nIn Autosignly, go to **Settings → Webhooks**, add the URL from step 2, and copy\\nthe signing key that Autosignly generates for it.\\n\\nBack in Twenty, paste that value into **Webhook signing key**.\\n\\nUntil this is set, documents still go out for signature, but nothing comes\\nback: the app refuses deliveries it cannot verify.\\n\\n## Trying it in a sandbox\\n\\nSandbox keys are free and work everywhere in this app. One difference matters:\\n**a sandbox sends no email and no SMS.**\\n\\nSo after you send, the panel does not just close. It shows an **Open signing\\npage** button with the signer's link, plus a copy button, and the same link is\\nsaved on the signature request record. **Signature status** on the source record\\nshows it again for whoever is up next.\\n\\nThe settings panel tells you which environment your key belongs to, and warns\\nyou in red when it is production.\\n\\nOnly the first signer gets a link immediately. The others are notified when\\ntheir turn comes, which in a sandbox means they are not notified at all.\\n\\n## Running Twenty on your own machine\\n\\nThe webhook URL in step 2 is built from your Twenty server's own address, so a\\nTwenty running locally produces one that points at your machine:\\n\\n```\\nhttp://localhost:2020/webhooks/server/<id>?c=<token>\\n```\\n\\nNothing outside your machine can reach that, which has two consequences.\\n\\n**Production keys will not accept it.** Autosignly validates the URL when you\\nsave the webhook, not when it first tries to deliver, and outside a sandbox it\\nrequires https. So a locally running Twenty cannot be paired with production\\nAutosignly at all: the save is refused with `webhook URL must use https`. That\\ncheck is what keeps real deliveries off plain http, so work in a sandbox rather\\nthan looking for a way around it.\\n\\n**A sandbox accepts it**, and the CLI carries the events the rest of the way:\\n\\n```bash\\nnpm install -g autosignly\\nautosignly login\\nautosignly listen --forward-to \\"http://localhost:2020/webhooks/server/<id>?c=<token>\\"\\n```\\n\\nPass the URL exactly as the settings panel printed it, token and all. The token\\nis what tells the app which workspace a delivery belongs to, so an event\\nforwarded without it is dropped.\\n\\nLeave `listen` running while you test. It prints every event as it arrives\\ntogether with the status your Twenty answered, which is usually enough to tell a\\nsignature that never arrived from one that was rejected on the way in.\\n\\n## Using it\\n\\n1. Open a Person, Company or Opportunity that has a PDF attached.\\n2. Open the command menu and choose **Send for signature**.\\n3. Pick the attachment, check the signer, pick the signature level.\\n4. Send.\\n\\nA **Signature request** record is created immediately and appears in the\\nSignature requests view and on the source record. As signers act, its status\\nmoves through Sent, then Completed, Declined or Expired. On completion the\\nsigned PDF is attached to it.\\n\\nEach signature also overwrites the attachment it was sent from, so the file on\\nthe record is the signed one rather than the draft that went out. The name does\\nnot change. Keep a copy elsewhere first if you need the unsigned original.\\n\\nThe command also appears on your own custom objects, where it opens the same\\nform with the signer fields blank.\\n\\nThe **Signature requests** list itself is read-only: records are written by the\\napp as documents go out and as signatures come in, so there is nothing there\\nworth typing by hand and an edit would be overwritten by the next update from\\nAutosignly. Its **How to send a document** button says where requests come from.\\nDeleting a request still works.\\n\\n## Requirements\\n\\n- Twenty 2.40.0 or newer\\n- An Autosignly account ([autosignly.eu](https://autosignly.eu))\\n\\n## Support\\n\\n- Issues: https://github.com/16it-pl/autosignly-integrations/issues\\n- API documentation: https://docs.16it.eu/docs/autosignly/integrations/api\\n- Email: support@autosignly.eu\\n\\nLicensed under Apache-2.0.\\n", "yarnLockChecksum": "28d927147571b56747198794043b964f", "packageJsonChecksum": "c4420b738edd848d58fedee72175044b", "universalIdentifier": "30a4b13f-ab17-4176-90f1-5cfba4f404d4", "applicationVariables": {"AUTOSIGNLY_API_KEY": {"label": "API key", "isSecret": true, "description": "API key created in Autosignly (Settings, API keys). Sandbox keys work here too.", "universalIdentifier": "88db4e7a-2412-42b3-b39a-6ad3d6b2fb5e"}, "AUTOSIGNLY_API_URL": {"label": "API base URL", "isSecret": false, "description": "Leave empty unless you were given a different endpoint. Origin plus /api, for example https://app.autosignly.eu/api. The version prefix is added automatically.", "universalIdentifier": "53fc0a8f-88d3-4c88-8ec2-7b1d4d1b10c1"}, "AUTOSIGNLY_API_SECRET": {"label": "API secret", "isSecret": true, "description": "The secret shown once when the API key was created.", "universalIdentifier": "41defbfe-af1e-4a0f-b670-a6d6322ed61a"}, "AUTOSIGNLY_WEBHOOK_SECRET": {"label": "Webhook signing key", "isSecret": true, "description": "Left empty on purpose: \\"Check and register\\" stores the key for you. Fill it in only when you registered from the Autosignly panel instead, or rotated the key there.", "universalIdentifier": "f3ba7707-f5c4-444b-827e-e5424621488f"}}, "settingsFrontComponent": {"universalIdentifier": "407c5ccd-ad72-43c2-8324-803c85010d67"}, "requiredServerVersionRange": ">=2.39.0", "defaultRoleUniversalIdentifier": "67f4ce0c-b0ab-4858-b06a-a04c41a2aabe"}, "pageLayouts": [], "publicAssets": [{"checksum": "be1d9d75267d1ead0dbb8d774ea001a9", "fileName": "autosignly.png", "filePath": "public/autosignly.png", "fileType": "png"}, {"checksum": "10aa83751a3e015f1f821299c97f462b", "fileName": "01-send-for-signature.png", "filePath": "public/gallery/01-send-for-signature.png", "fileType": "png"}, {"checksum": "c47ca2b3a9b79b9fd50ca86aa5f48ff6", "fileName": "02-multiple-signers.png", "filePath": "public/gallery/02-multiple-signers.png", "fileType": "png"}, {"checksum": "8263d8365edb998eae9bebd4d18125b6", "fileName": "03-signature-status.png", "filePath": "public/gallery/03-signature-status.png", "fileType": "png"}, {"checksum": "41f67a7548fb278f9cf30e6b998f5344", "fileName": "04-settings.png", "filePath": "public/gallery/04-settings.png", "fileType": "png"}], "translations": {}, "logicFunctions": [{"name": "autosignly-list-record-signatures", "description": "Signature requests made from one record, with signer progress.", "handlerName": "default.config.handler", "timeoutSeconds": 