, "objectUniversalIdentifier": "20202020-3319-4234-a34c-82d5c0e881a6", "relationTargetFieldMetadataUniversalIdentifier": "d554d5c1-48d4-4ee8-879d-bb7fe11fe925", "relationTargetObjectMetadataUniversalIdentifier": "6e6de038-df90-4dc3-a1bd-fb9c15b98308"}, {"icon": "IconFileCheck", "name": "approvedContracts", "type": "RELATION", "label": "Approved contracts", "description": "Contracts this member approved or rejected.", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "7dde2294-c596-4234-8aff-54e28af08a1c", "objectUniversalIdentifier": "20202020-3319-4234-a34c-82d5c0e881a6", "relationTargetFieldMetadataUniversalIdentifier": "cd548383-5560-4b90-a8ac-fb88f6483fe2", "relationTargetObjectMetadataUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591"}, {"icon": "IconTargetArrow", "name": "opportunity", "type": "RELATION", "label": "Opportunity", "description": "The Opportunity this contract belongs to.", "universalSettings": {"onDelete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "opportunityId"}, "universalIdentifier": "8abe646d-41d4-483d-8f22-09859a1bce26", "objectUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591", "relationTargetFieldMetadataUniversalIdentifier": "0a9f9101-7093-4ef8-8087-671964f5b642", "relationTargetObjectMetadataUniversalIdentifier": "20202020-9549-49dd-b2b2-883999db8938"}, {"icon": "IconUserUp", "name": "submittedBy", "type": "RELATION", "label": "Submitted by", "description": "The member who submitted this contract for review.", "universalSettings": {"onDelete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "submittedById"}, "universalIdentifier": "9288433a-6972-4a3f-b7d2-5bbf655ad0c2", "objectUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591", "relationTargetFieldMetadataUniversalIdentifier": "310b6c4e-22ab-4af5-bfc0-caf059128bf5", "relationTargetObjectMetadataUniversalIdentifier": "20202020-3319-4234-a34c-82d5c0e881a6"}, {"icon": "IconFileText", "name": "contract", "type": "RELATION", "label": "Contract", "description": "The contract this decision applies to.", "universalSettings": {"onDelete": "CASCADE", "relationType": "MANY_TO_ONE", "joinColumnName": "contractId"}, "universalIdentifier": "b949d9af-6b11-4ff3-8a76-7862bf90ceae", "objectUniversalIdentifier": "6e6de038-df90-4dc3-a1bd-fb9c15b98308", "relationTargetFieldMetadataUniversalIdentifier": "f2754979-61fa-45eb-aefb-aa9ede9a73ef", "relationTargetObjectMetadataUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591"}, {"icon": "IconUserCheck", "name": "approver", "type": "RELATION", "label": "Approver", "description": "The Manager who decided on this contract.", "universalSettings": {"onDelete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "approverId"}, "universalIdentifier": "cd548383-5560-4b90-a8ac-fb88f6483fe2", "objectUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591", "relationTargetFieldMetadataUniversalIdentifier": "7dde2294-c596-4234-8aff-54e28af08a1c", "relationTargetObjectMetadataUniversalIdentifier": "20202020-3319-4234-a34c-82d5c0e881a6"}, {"icon": "IconUserCheck", "name": "decidedBy", "type": "RELATION", "label": "Decided by", "description": "The Manager who recorded this decision.", "universalSettings": {"onDelete": "SET_NULL", "relationType": "MANY_TO_ONE", "joinColumnName": "decidedById"}, "universalIdentifier": "d554d5c1-48d4-4ee8-879d-bb7fe11fe925", "objectUniversalIdentifier": "6e6de038-df90-4dc3-a1bd-fb9c15b98308", "relationTargetFieldMetadataUniversalIdentifier": "67718dfb-37a1-46a6-961a-ec5d48a36c5f", "relationTargetObjectMetadataUniversalIdentifier": "20202020-3319-4234-a34c-82d5c0e881a6"}, {"icon": "IconGavel", "name": "approvalDecisions", "type": "RELATION", "label": "Approval decisions", "description": "History of approve/reject decisions for this contract.", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "f2754979-61fa-45eb-aefb-aa9ede9a73ef", "objectUniversalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591", "relationTargetFieldMetadataUniversalIdentifier": "b949d9af-6b11-4ff3-8a76-7862bf90ceae", "relationTargetObjectMetadataUniversalIdentifier": "6e6de038-df90-4dc3-a1bd-fb9c15b98308"}], "skills": [], "indexes": [], "objects": [{"icon": "IconFileText", "fields": [{"icon": "IconFileText", "name": "name", "type": "TEXT", "label": "Name", "description": "Contract title or reference.", "universalIdentifier": "08a4f050-7c85-463e-9aa4-009d0213ba05"}, {"icon": "IconCashBanknote", "name": "paymentTermsCustomer", "type": "TEXT", "label": "Payment terms (customer)", "description": "How the customer pays us (e.g. monthly over 12 months).", "universalIdentifier": "df60b392-c2bf-4460-a3ba-9846a7da98f7"}, {"icon": "IconCashBanknoteOff", "name": "paymentTermsSupplier", "type": "TEXT", "label": "Payment terms (supplier)", "description": "How we pay the supplier (e.g. single upfront installment). When neither this field nor the contract states it, the AI review fills in the standard: a single payment 30 days after signature.", "universalIdentifier": "94443e7c-c83e-4542-93f7-63dad2207a75"}, {"icon": "IconProgressCheck", "name": "status", "type": "SELECT", "label": "Status", "options": [{"id": "fd147573-5cd0-455d-9c1d-5a1f1f3dd5b3", "color": "gray", "label": "Draft", "value": "DRAFT", "position": 0}, {"id": "3dea697a-77f4-49d4-aa44-f5d8662d260b", "color": "blue", "label": "Pending AI review", "value": "PENDING_AI_REVIEW", "position": 1}, {"id": "fbc4bab6-17ce-4544-a21d-aeb1d92d83ec", "color": "orange", "label": "Pending manager approval", "value": "PENDING_MANAGER_APPROVAL", "position": 2}, {"id": "660dce9e-d054-462a-b50f-0335d54446f1", "color": "green", "label": "Approved", "value": "APPROVED", "position": 3}, {"id": "7292e345-7d05-4564-8a56-8378f1359c96", "color": "red", "label": "Rejected", "value": "REJECTED", "position": 4}], "description": "Lifecycle of the contract review and approval.", "defaultValue": "'DRAFT'", "universalIdentifier": "128da9a5-ffba-4310-9792-5be2805de9f5"}, {"icon": "IconSparkles", "name": "aiReviewSummary", "type": "TEXT", "label": "AI review summary", "isNullable": true, "description": "Human-readable summary produced by the AI review.", "universalIdentifier": "e1b7f3eb-eadf-4644-92d4-ef44954ef179"}, {"icon": "IconAlertTriangle", "name": "aiPaymentMismatch", "type": "SELECT", "label": "AI payment mismatch", "options": [{"id": "16a115a7-7b44-4073-9715-89203605470b", "color": "gray", "label": "Unknown", "value": "UNKNOWN", "position": 0}, {"id": "55247810-5361-4a18-b094-84e3f1191a79", "color": "green", "label": "Match", "value": "MATCH", "position": 1}, {"id": "e783ade0-e7e9-42d4-89d9-68944eacdd61", "color": "red", "label": "Mismatch", "value": "MISMATCH", "position": 2}], "description": "Whether customer and supplier payment terms are consistent.", "defaultValue": "'UNKNOWN'", "universalIdentifier": "2223a01a-25a1-4c2d-a13e-6044bfc3df62"}, {"icon": "IconShieldCheck", "name": "aiRiskLevel", "type": "SELECT", "label": "AI risk level", "options": [{"id": "98306cd9-e9cb-43fb-8a35-f2d1c8ce8d51", "color": "green", "label": "Verde", "value": "VERDE", "position": 0}, {"id": "4f64ec67-7b70-43d4-812a-1631964eb1b1", "color": "yellow", "label": "Amarelo", "value": "AMARELO", "position": 1}, {"id": "029e55fa-61fb-480f-b8f5-a585388da4e9", "color": "red", "label": "Vermelho", "value": "VERMELHO", "position": 2}], "isNullable": true, "description": "Nível de risco geral apurado pela revisão de IA (Verde/Amarelo/Vermelho).", "universalIdentifier": "40bb9271-9f33-4e52-b4b6-91cc58a412dc"}, {"icon": "IconClock", "name": "submittedAt", "type": "DATE_TIME", "label": "Submitted at", "isNullable": true, "description": "When the contract was submitted for review.", "defaultValue": null, "universalIdentifier": "324d19ae-98c7-4c1c-ae81-258619222ec7"}, {"icon": "IconClockCheck", "name": "decidedAt", "type": "DATE_TIME", "label": "Decided at", "isNullable": true, "description": "When a manager approved or rejected the contract.", "defaultValue": null, "universalIdentifier": "e330567f-d443-4d21-ad7a-307576da6e19"}, {"icon": "IconHistory", "name": "aiPaymentTermsSnapshot", "type": "TEXT", "label": "AI payment terms snapshot", "isNullable": true, "description": "Internal: payment terms written by the last AI review, used to tell AI output apart from manual input on a re-review.", "universalIdentifier": "7b1c9d24-3f68-4a05-9e13-c4d2a86f5b70"}, {"icon": "IconCalendarEvent", "name": "dataInicio", "type": "DATE", "label": "Data de início", "isNullable": true, "description": "Data de início de vigência do contrato.", "defaultValue": null, "universalIdentifier": "18dd3809-2832-484a-87b6-c0a74bf70c56"}, {"icon": "IconCalendarDue", "name": "dataTermino", "type": "DATE", "label": "Data de término", "isNullable": true, "description": "Data de vencimento da vigência atual do contrato — usada para disparar o alerta de renovação.", "defaultValue": null, "universalIdentifier": "28eb43b7-fcfb-4259-a894-cef533ba2292"}, {"icon": "IconRefresh", "name": "estagioRenovacao", "type": "SELECT", "label": "Estágio de renovação", "options": [{"id": "f3f27751-d3ea-4d1b-b2db-4d36179125f3", "color": "green", "label": "Ativo", "value": "ATIVO", "position": 0}, {"id": "7517bf3d-b13e-4fa3-b199-b2280fe30267", "color": "orange", "label": "Renovação iniciada", "value": "RENOVACAO_INICIADA", "position": 1}, {"id": "5a7e5049-d115-4bb3-84b0-941b00c85f8d", "color": "blue", "label": "Renovado", "value": "RENOVADO", "position": 2}, {"id": "44755541-0569-418d-997c-8fcdb0025d2c", "color": "gray", "label": "Encerrado", "value": "ENCERRADO", "position": 3}], "isNullable": true, "description": "Onde o contrato está no ciclo de renovação.", "defaultValue": "'ATIVO'", "universalIdentifier": "83f2704a-bb13-4dd9-9bf2-ec792ba800b3"}], "namePlural": "contracts", "description": "A contract under review for an Opportunity, with its file attached (PDF, .docx, .doc or .rtf) and an AI clause review before manager approval.", "labelPlural": "Contracts", "nameSingular": "contract", "labelSingular": "Contract", "universalIdentifier": "45a32a16-21a5-4142-ad6b-7949cacad591", "labelIdentifierFieldMetadataUniversalIdentifier": "08a4f050-7c85-463e-9aa4-009d0213ba05"}, {"icon": "IconGavel", "fields": [{"icon": "IconGavel", "name": "name", "type": "TEXT", "label": "Name", "description": "Short label for the decision record.", "universalIdentifier": "80cd5548-93db-43eb-b3c3-953572e973fe"}, {"icon": "IconCheckbox", "name": "decision", "type": "SELECT", "label": "Decision", "options": [{"id": "35ff0df0-202b-4abd-8264-98834c48c502", "color": "green", "label": "Approve", "value": "APPROVE", "position": 0}, {"id": "cbb44164-7e65-468f-98ab-788315c77db1", "color": "red", "label": "Reject", "value": "REJECT", "position": 1}], "description": "The manager decision.", "universalIdentifier": "e8769cd6-4e43-43bd-86c9-18ed19d8e3c2"}, {"icon": "IconMessage", "name": "comment", "type": "TEXT", "label": "Comment", "isNullable": true, "description": "Optional reviewer comment.", "universalIdentifier": "e8263f3c-29c2-4fb9-b9e8-43e2a68dbdd2"}, {"icon": "IconClockCheck", "name": "decidedAt", "type": "DATE_TIME", "label": "Decided at", "isNullable": true, "description": "When the decision was recorded.", "defaultValue": null, "universalIdentifier": "becbc35b-dd19-4ca2-bbc7-801a65118abf"}], "namePlural": "approvalDecisions", "description": "Append-only audit record of a manager approving or rejecting a Contract.", "labelPlural": "Approval Decisions", "nameSingular": "approvalDecision", "labelSingular": "Approval Decision", "universalIdentifier": "6e6de038-df90-4dc3-a1bd-fb9c15b98308", "labelIdentifierFieldMetadataUniversalIdentifier": "80cd5548-93db-43eb-b3c3-953572e973fe"}], "viewFields": [{"position": 10, "isVisible": true, "universalIdentifier": "6f2d9f81-2bf7-4030-af1e-0fffe3468793", "viewUniversalIdentifier": "20202020-a003-4a03-8a03-0aa0b1ca3001", "fieldMetadataUniversalIdentifier": "0a9f9101-7093-4ef8-8087-671964f5b642", "viewFieldGroupUniversalIdentifier": "20202020-a003-4a03-8a03-0aa0b1ca3102"}], "application": {"logo": "public/contract-approval-icon.png", "author": "Excelium Tech", "category": "Sales", "description": "AI contract review plus a role-enforced approval workflow for Opportunities. An AI review reads the attached PDF and flags risky clauses (notably customer-vs-supplier payment-terms mismatches); only Manager members can approve or reject.", "displayName": "Contract Approval", "galleryImages": ["public/cover.generated.png"], "aboutDescription": "# Contract Approval\\n\\nAI contract review plus a **role-enforced** approval workflow for Twenty Opportunities.\\n\\nA salesperson creates a **Contract** linked to an Opportunity, attaches the contract PDF, and submits it for review. An AI review reads the PDF and flags risky or inconsistent clauses — notably a **customer-vs-supplier payment-terms mismatch** (e.g. the customer pays monthly while the supplier must be paid in a single upfront installment). Managers/partners (**Gerente/Sócio**) then approve or reject, and **only that role can approve**.\\n\\n## What it installs\\n\\n- **Contract** (custom object, related to Opportunity): payment terms (customer/supplier), lifecycle `status`, AI review summary, structured AI findings, `aiPaymentMismatch`, approver, submitter, and timestamps. The contract PDF attaches to the Contract via the native Attachment relation.\\n- **Renewal tracking** on Contract: `dataInicio` / `dataTermino` (vigência) and `estagioRenovacao` (`ATIVO` → `RENOVACAO_INICIADA` → `RENOVADO` / `ENCERRADO`, default `ATIVO`). See [Renewal tracking](#renewal-tracking).\\n- **Approval Decision** (custom object, child of Contract): the append-only audit of who decided what, when, and why (`decidedBy`, `decision`, `comment`, `decidedAt`).\\n- **Gerente/Sócio** role: assignable to users; the record-decision function checks this role before accepting an approval. A declarative field-permission on `Contract.status` is shipped as defense-in-depth.\\n- **Logic functions**: `ai-review`, `submit-for-review`, and `record-decision` (all route-auth'd), plus a no-op `post-install`.\\n- **Front-component actions** on a Contract: **Submit for review**, **Approve**, **Reject**.\\n- **Pending approvals** view: contracts with `status = pending_manager_approval` — the manager's work queue.\\n\\n## How it works\\n\\n1. **Submit for review** sets `status = pending_ai_review`, records the submitter, then runs the AI review directly (no workflow required).\\n2. **AI review** fetches the Contract's most-recent PDF attachment (signed URL), sends it to the Anthropic Messages API as a `document` block with a broad clause-review prompt, writes back `aiReviewSummary` / `aiFindings` / `aiPaymentMismatch`, and advances `status = pending_manager_approval`. Supplier payment terms absent from the contract fall back to the standard — see [Supplier payment default](#supplier-payment-default).\\n3. **Approve / Reject** calls the route-auth'd `record-decision` function, which resolves the **invoking user** and verifies they hold the Gerente/Sócio role before writing an Approval Decision (`decidedBy` = the actor) and updating the contract. A non-manager attempt is refused with a clear message and nothing is written.\\n\\n## Setup\\n\\n1. Install the app.\\n2. In **Settings → Apps**, set `ANTHROPIC_API_KEY` (required for AI review). Optionally set `LLM_MODEL` (defaults to a multimodal Claude model). Without the key, the AI step degrades gracefully: it writes a \\"not configured\\" summary and the contract awaits manual manager review.\\n3. Assign the **Gerente/Sócio** role to the members who may approve.\\n\\n## Supplier payment default\\n\\nWhen a contract does not state how the supplier is paid, the review applies the Excelium standard: a **single payment (à vista) 30 days after signature** (`src/constants/payment-terms.ts`).\\n\\nThe *format* matters as much as the term. Paying the supplier in one shot is exactly what creates cash-flow exposure when we bill the customer in installments — money goes out at once while it comes in over months. That comparison is the point of the whole check.\\n\\nThe default is applied in two places, deliberately split:\\n\\n- **In the prompt** — the model is told the standard so it can still return a `match`/`mismatch` verdict instead of `unknown`, plus an explicit rule: customer paying in installments/recurring + supplier paid in a single installment ⇒ `mismatch`, with a `vermelho` finding flagged for manual review. It is also told *not* to invent a clause — when the contract is silent it must return `supplierPaymentTerms: null`.\\n- **In code** — `paymentTermsSupplier` is then filled from that null with the default. Manual input is never overwritten, and an extracted clause always wins over the default.\\n\\nThe stored value carries its own label — `Parcela única (à vista) em 30 dias após a assinatura do contrato (padrão — não explícito no contrato)` — and the AI-review Note states the same. This is the point of the design: a presumption must never be readable as a contractual term. To change the standard, edit `DEFAULT_SUPPLIER_PAYMENT_TERMS_DAYS` / `DEFAULT_SUPPLIER_PAYMENT_TERMS_SHORT`; the prompt, the stored value and the Note all derive from them.\\n\\n### Mismatch backstop\\n\\nThe prompt is what actually reads the contract, so it is the primary mechanism. On top of it, `ai-review-contract` runs a narrow guard (`paysInInstallments`, a pt-br text heuristic): when the review returns **`unknown`**, the supplier side is the **applied default** (so it is known to be a single payment), and the customer terms read as installments/recurring, the verdict is escalated to `MISMATCH`.\\n\\nIt only ever escalates a non-verdict — an explicit `MATCH` or `MISMATCH` from the review is never overridden — and it stands down when supplier terms were filled by hand, since those may themselves be an installment plan. A false positive here costs one extra manager glance; a false negative costs cash.\\n\\n## Renewal tracking\\n\\n`dataInicio`, `dataTermino` and `estagioRenovacao` support renewal follow-up: `dataTermino` is the current term's expiry and is what any renewal alert should key off; `estagioRenovacao` is where the contract sits in the renewal cycle. Both are nullable — a contract with no `dataTermino` is invisible to every renewal report, so backfilling existing contracts is a prerequisite, not an optimisation.\\n\\n**These three fields were first created directly in the production workspace** (via the metadata API, under the workspace's own application) and only afterwards declared here. Their `universalIdentifier`s in `src/constants/universal-identifiers.ts` are therefore **pinned to the live UUIDs** rather than freshly generated — `scripts/generate-universal-identifiers.mjs` must not be allowed to overwrite them.\\n\\nConsequence for the first deploy that ships these declarations: the live fields belong to a *different* `applicationId` than the Contract object, so they are outside this app's metadata diff. The deploy will try to **create** them rather than adopt them, and creation collides with the existing fields on the `(object, name)` uniqueness constraint. Before that deploy, either confirm the migration adopts fields by `universalIdentifier`, or delete the three workspace-owned fields first and let the app recreate them. Deleting them also invalidates any dashboard widget that references their field-metadata IDs — those widgets must be repointed afterwards.\\n\\n## Graceful degradation\\n\\n- **No LLM key** → AI review writes a \\"not configured\\" summary and leaves the status for manual review.\\n- **No downloadable PDF** → the AI review falls back to the structured payment-terms fields.\\n\\n## Development\\n\\n```bash\\nyarn install\\nyarn twenty dev:build\\nyarn typecheck\\nyarn lint\\nyarn test        # unit tests (offline, fixtures/mocks)\\n```\\n\\nRegenerate all universal identifiers:\\n\\n```bash\\nnode scripts/generate-universal-identifiers.mjs\\n```\\n\\n## Notes / out of scope\\n\\n- Live-instance validation (real PDF → LLM round trip, front-component→route end-user auth, install-time workflow seeding) is deferred; unit tests use mocks.\\n- Email notifications require a connected account and are not install-seedable; the pending-approvals view is the notification surface.\\n", "yarnLockChecksum": "fad70d2ae9ff19b29a97223746874dba", "packageJsonChecksum": "3547fbf02faa0d52c9b56ffcde47fc85", "universalIdentifier": "e18866a9-afd0-440a-9855-1e7e9e693a74", "applicationVariables": {"LLM_MODEL": {"isSecret": false, "description": "Anthropic model id used for the contract review. Defaults to \\"claude-3-5-sonnet-latest\\" when unset. Must be a multimodal model that accepts PDF document blocks.", "universalIdentifier": "43bc75b0-ef4c-42ec-848e-35297e90364e"}, "ANTHROPIC_API_KEY": {"isSecret": true, "description": "Anthropic API key used by the AI contract-review step to read the attached PDF and flag risky clauses. When unset, the review degrades gracefully and contracts await manual manager review.", "universalIdentifier": "2f9824be-df6f-4065-aa4e-a8313d201ef8"}}, "postInstallLogicFunction": {"universalIdentifier": "65b60977-844a-4230-aacc-0dff6e2eb69d", "shouldRunSynchronously": true, "shouldRunOnVersionUpgrade": false}, "requiredServerVersionRange": ">=2.20.0", "defaultRoleUniversalIdentifier": "77fda223-b7a9-4f4a-844e-4a475f2adf0c"}, "pageLayouts": [], "publicAssets": [{"checksum": "1bd5a40fbe0248e3bb0b0bbace5b619e", "fileName": "contract-approval-icon.png", "filePath": "public/contract-approval-icon.png", "fileType": "png"}, {"checksum": "56a06208f93970e451ae25e4a250b17a", "fileName": "cover.generated.png", "filePath": "public/cover.generated.png", "fileType": "png"}], "logicFunctions": [{"name": "post-install", "description": "Post-install hook for the Contract Approval app (no workflow seeding; the app runs via front-component actions).", "handlerName": "