cd4c0059-e3f8-4dcd-a65a-9dc0aff425ed	d64b5231-682b-433f-a201-3ff75d02fce2	Retell Sync for Twenty	518155bd-aaab-4020-a44e-a1d1f0e0e11d	\N	{}	{}	\N	2026-10-31 12:35:41.356546+00	2026-10-31 13:26:36.614291+00	\N	\N	npm	twenty-retell-sync	\N	0.1.25	f	{"roles": [{"label": "Retell Sync for Twenty default function role", "description": "Retell Sync for Twenty default function role", "fieldPermissions": [], "objectPermissions": [], "universalIdentifier": "ecc5546d-1441-42d6-94db-63bc38d8c51e", "canReadAllObjectRecords": true, "canUpdateAllObjectRecords": true, "canDestroyAllObjectRecords": false, "rowLevelPermissionPredicates": [], "canSoftDeleteAllObjectRecords": true, "rowLevelPermissionPredicateGroups": [], "permissionFlagUniversalIdentifiers": ["9faa55f7-2606-566b-9e1d-aefbedbd0136"]}], "views": [], "agents": [], "fields": [{"icon": "IconClockOff", "name": "retellDoNotCallAt", "type": "DATE_TIME", "label": "Retell do not call changed at", "description": "When the do-not-call flag last changed", "universalIdentifier": "6bba93a0-30d8-40fe-be2e-746e239473f6", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconPhoneCall", "name": "retellCalls", "type": "RELATION", "label": "Retell Calls", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "7ed1ef86-c1ad-4a37-89c1-ff8341fd533d", "objectUniversalIdentifier": "20202020-9549-49dd-b2b2-883999db8938", "relationTargetFieldMetadataUniversalIdentifier": "a09f86d8-d803-482f-ab47-62f0a1ebb4ff", "relationTargetObjectMetadataUniversalIdentifier": "5620c9c9-eb86-4d6e-8a55-984a1a10bfab"}, {"icon": "IconKey", "name": "retellContactId", "type": "TEXT", "label": "Retell contact ID", "description": "Identifier of this person's contact in Retell", "universalIdentifier": "84ddda6a-b0b0-405f-a4f8-50503d40aba4", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconClock", "name": "retellLastContactedAt", "type": "DATE_TIME", "label": "Retell last contacted at", "description": "Start of the newest Retell call or chat with this person", "universalIdentifier": "963cf1d2-55f2-489b-bcb3-fa10c5ff8f5a", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconMessageCircle", "name": "retellChats", "type": "RELATION", "label": "Retell Chats", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "97480f62-cb19-48ae-9ece-4e3eacb523ea", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213", "relationTargetFieldMetadataUniversalIdentifier": "bc460ae5-b30a-43f6-8da4-e14440759a18", "relationTargetObjectMetadataUniversalIdentifier": "8f36e64d-08a1-4176-9490-be534212268e"}, {"icon": "IconMessageCircle", "name": "retellChats", "type": "RELATION", "label": "Retell Chats", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "a302b47d-d8fc-45fb-aaff-85a165c0c337", "objectUniversalIdentifier": "20202020-9549-49dd-b2b2-883999db8938", "relationTargetFieldMetadataUniversalIdentifier": "91a34c81-87f0-4cf0-b4ea-5da0e81cb8c8", "relationTargetObjectMetadataUniversalIdentifier": "8f36e64d-08a1-4176-9490-be534212268e"}, {"icon": "IconPhoneOff", "name": "retellDoNotCall", "type": "BOOLEAN", "label": "Retell do not call", "description": "Mirrors the do-not-call flag of the contact in Retell; it stops outbound calls and SMS that honour it", "defaultValue": false, "universalIdentifier": "c940d39b-b7ce-48af-b3fc-4e5715d9ca58", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconInfoCircle", "name": "retellDoNotCallSource", "type": "SELECT", "label": "Retell do not call source", "options": [{"id": "fb6a9c29-20fd-55eb-b341-330cc0c9fa27", "color": "red", "label": "Retell: asked on a call", "value": "RETELL_CALL", "position": 0}, {"id": "52f7c233-6622-594f-9b09-b9efca622013", "color": "orange", "label": "Retell: contact (SMS opt-out or dashboard)", "value": "RETELL_CONTACT", "position": 1}, {"id": "87f0b232-2875-5c26-84f6-3d4c738b0554", "color": "gray", "label": "Twenty", "value": "TWENTY", "position": 2}], "description": "Where the last change of the do-not-call flag came from", "universalIdentifier": "e90cdacd-fceb-4cc1-a2a5-f0de9a7d8556", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213"}, {"icon": "IconPhoneCall", "name": "retellCalls", "type": "RELATION", "label": "Retell Calls", "universalSettings": {"relationType": "ONE_TO_MANY"}, "universalIdentifier": "fe6de734-b0c0-42a4-8481-ebe918f6c86a", "objectUniversalIdentifier": "20202020-e674-48e5-a542-72570eee7213", "relationTargetFieldMetadataUniversalIdentifier": "2dd580de-9d62-41de-81a8-074b59594bd9", "relationTargetObjectMetadataUniversalIdentifier": "5620c9c9-eb86-4d6e-8a55-984a1a10bfab"}], "skills": [{"icon": "IconPhoneCall", "name": "retell", "label": "Retell calls and SMS", "content": "You work with Retell AI voice and SMS agents through the Retell Sync app.\\n\\n## Data\\n\\n- **Retell Calls** (`retellCall`): one record per phone call. Key fields: `callId` (Retell id, e.g. call_abc123), `direction` (INBOUND or OUTBOUND), `callStatus`, `fromNumber`, `toNumber`, `startedAt`, `endedAt`, `durationMs`, `disconnectionReason`, `summary`, `sentiment`, `successful`, `transcript`, `recording` (link to the audio), `analysis` (custom post-call data), `agentName`, `person`, `opportunity`.\\n- **Retell Chats** (`retellChat`): one record per SMS or web chat, same idea with `chatId` and `userNumber`.\\n- On **Person**: `retellDoNotCall` (true = never call or text), `retellDoNotCallSource` (RETELL_CALL, RETELL_CONTACT or TWENTY), `retellLastContactedAt`, and the relations to their calls and chats.\\n- Calls and chats are linked to a Person by phone number and to an Opportunity when the call carried its id.\\n\\n## Tools\\n\\n- `app_retell_get_call`: re-reads one call from Retell by `callId`, saves it and returns summary, status and a fresh recording link. Read-only on the Retell side, safe to call. Use it when a record looks incomplete or its recording link has expired.\\n- `app_retell_call_person`: places a real outbound phone call to a Person (`personId`, optional `opportunityId`, `fromNumber`, `agentId`, `variables`, `idempotencyKey`).\\n- `app_retell_send_sms`: starts a real SMS conversation with a Person (same inputs, no `idempotencyKey`). The Retell chat agent writes the first message itself; put the reason to write in `variables`, never a ready text.\\n- `app_retell_set_dnc`: sets or clears do-not-call on a Person and on Retell (`personId`, `doNotCall`).\\n\\n## Rules\\n\\n1. A call or an SMS reaches a real person and costs money. Never run `app_retell_call_person` or `app_retell_send_sms` directly: always propose the call for approval with the exact arguments, one person at a time.\\n2. Before proposing one, read the Person and check `retellDoNotCall`. If it is true, do not propose; say the person is do-not-call. Do not clear the flag to get around it unless the user explicitly asks to clear it.\\n3. Pass `opportunityId` when the user talks about a deal, so the finished call links to it.\\n4. The new call record appears in Retell Calls when the call ends, usually within a minute or two. To check it earlier, call `app_retell_get_call` with the returned `callId`.\\n5. When a tool returns an error from Retell (country not supported, number without SMS, do-not-call), report the message as it is; do not retry with other numbers on your own.\\n6. Use `app_retell_set_dnc` only on an explicit request (\\"they asked us not to call\\"), and propose it for approval.\\n\\n## Building workflows with these actions\\n\\nEach tool is also a workflow step. Add it as a LOGIC_FUNCTION step: find its id with `list_logic_function_tools` (names `retell-call-person`, `retell-send-sms`, `retell-get-call`, `retell-set-dnc`) and pass it as settings.input.logicFunctionId; fill the step input from earlier steps, for example `{{trigger.record.id}}` for personId. Load the workflow-building skill first.\\n\\nCommon recipes:\\n- **New lead, call back**: trigger DATABASE_EVENT on person created (or opportunity created, then use its pointOfContact as the person) -> optional filter on source or stage -> retell-call-person with personId and opportunityId.\\n- **Missed call, text back**: trigger on retellCall created -> filter direction INBOUND and a short durationMs or a disconnectionReason such as voicemail -> retell-send-sms to the call's person.\\n- **Follow-up task**: trigger on retellCall created -> filter successful is false or sentiment Negative -> CREATE_RECORD task linked to the call's person, with the summary in the body.\\n- **Do-not-call from your own field**: trigger on person updated with your field -> retell-set-dnc with the new value.\\n- **Scheduled re-check**: CRON trigger -> find calls without summary -> retell-get-call for each.\\n\\nA workflow runs without approval, so tell the user plainly that an activated \\"call\\" or \\"SMS\\" workflow will contact people automatically, and suggest testing it on one record before activating.", "description": "Use for anything about Retell AI calls, SMS chats, voice agents, calling or texting a person, do-not-call, or workflows that call, text or follow up on calls.", "universalIdentifier": "f59984d0-ca9d-460c-9c7d-30cd66bc56c7"}], "indexes": [], "objects": [{"icon": "IconPhoneCall", "fields": [{"icon": "IconKey", "name": "callId", "type": "TEXT", "label": "Call ID", "universalIdentifier": "df92cdd0-3303-41b1-b407-4221d7719c3b"}, {"icon": "IconRobot", "name": "agentId", "type": "TEXT", "label": "Agent ID", "universalIdentifier": "c3971c50-3053-4473-9754-5a4749dfa5da"}, {"icon": "IconRobot", "name": "agentName", "type": "TEXT", "label": "Agent name", "universalIdentifier": "f6ab70ef-c3ce-4c62-a7dd-22d6b99ee69e"}, {"icon": "IconArrowsExchange", "name": "direction", "type": "SELECT", "label": "Direction", "options": [{"id": "37f6ce01-c726-5008-906a-5a49b02c1d41", "color": "blue", "label": "Inbound", "value": "INBOUND", "position": 0}, {"id": "c6e5af36-e9c5-542c-897f-bbc8c3c4d562", "color": "green", "label": "Outbound", "value": "OUTBOUND", "position": 1}], "universalIdentifier": "d09f3905-3236-4cdc-83d5-f594bab60e75"}, {"icon": "IconPhone", "name": "callType", "type": "TEXT", "label": "Call type", "universalIdentifier": "854bcfbe-f7f1-4e31-8042-eee979eacfe4"}, {"icon": "IconActivity", "name": "callStatus", "type": "TEXT", "label": "Call status", "universalIdentifier": "321fd9e3-cb76-49ff-ab76-94490bd3d8f4"}, {"icon": "IconPhoneOutgoing", "name": "fromNumber", "type": "TEXT", "label": "From number", "universalIdentifier": "bc8d054e-0071-42b1-a7c5-a861f81adff7"}, {"icon": "IconPhoneIncoming", "name": "toNumber", "type": "TEXT", "label": "To number", "universalIdentifier": "8d7666cb-a541-4481-86ac-c3f537e66dff"}, {"icon": "IconClock", "name": "startedAt", "type": "DATE_TIME", "label": "Started at", "universalIdentifier": "83d58998-e6dc-4284-a486-95bf10dd4422"}, {"icon": "IconClockStop", "name": "endedAt", "type": "DATE_TIME", "label": "Ended at", "universalIdentifier": "ad861d78-b0c3-470f-9bdf-620a9ae88825"}, {"icon": "IconHourglass", "name": "durationMs", "type": "NUMBER", "label": "Duration (ms)", "universalIdentifier": "df2557c0-fbf9-40b1-88df-9eadeda34f7f"}, {"icon": "IconPhoneOff", "name": "disconnectionReason", "type": "TEXT", "label": "Disconnection reason", "universalIdentifier": "b798ccff-1c0a-40ec-af95-304b632a4dec"}, {"icon": "IconPlugConnected", "name": "connection", "type": "SELECT", "label": "Connection", "options": [{"id": "ac65f148-b133-556e-9757-f597bf06c033", "color": "green", "label": "Connected", "value": "CONNECTED", "position": 0}, {"id": "296fc101-f5b2-5b8e-b17e-f715bb7df981", "color": "orange", "label": "Not connected", "value": "NOT_CONNECTED", "position": 1}, {"id": "344b6301-6ed6-5748-9f2f-c050568b0a94", "color": "red", "label": "Error", "value": "ERROR", "position": 2}], "universalIdentifier": "b0c0407a-90b0-42c1-9880-b2e7e0c6eca7"}, {"icon": "IconArrowForwardUp", "na